(function(window){
  'use strict';

  function sleep(ms) {
    return new Promise(function(resolve) { setTimeout(resolve, ms); });
  }

  class Html5Qrcode {
    constructor(regionId) {
      this.regionId = regionId;
      this.container = null;
      this.video = null;
      this.stream = null;
      this.detector = null;
      this.running = false;
      this.timer = null;
      this.onSuccess = null;
      this.onError = null;
      this.delayMs = 250;
    }

    async start(cameraConfig, scanConfig, onSuccess, onError) {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error('Camera API is not available in this browser.');
      }
      if (!window.BarcodeDetector) {
        throw new Error('BarcodeDetector API is not supported in this browser.');
      }

      this.container = document.getElementById(this.regionId);
      if (!this.container) {
        throw new Error('QR container not found.');
      }

      this.stop().catch(function(){});
      this.onSuccess = typeof onSuccess === 'function' ? onSuccess : null;
      this.onError = typeof onError === 'function' ? onError : null;
      this.delayMs = Math.max(150, Math.floor(1000 / ((scanConfig && scanConfig.fps) || 10)));

      this.container.innerHTML = '';
      this.video = document.createElement('video');
      this.video.setAttribute('autoplay', 'true');
      this.video.setAttribute('muted', 'true');
      this.video.setAttribute('playsinline', 'true');
      this.video.style.width = '100%';
      this.video.style.maxWidth = '320px';
      this.video.style.borderRadius = '8px';
      this.video.style.display = 'block';
      this.container.appendChild(this.video);

      const constraints = {
        video: cameraConfig && typeof cameraConfig === 'object'
          ? cameraConfig
          : { facingMode: 'environment' }
      };

      this.stream = await navigator.mediaDevices.getUserMedia(constraints);
      this.video.srcObject = this.stream;
      await this.video.play();

      this.detector = new BarcodeDetector({ formats: ['qr_code'] });
      this.running = true;
      this.scanLoop();

      return this;
    }

    async scanLoop() {
      while (this.running) {
        try {
          if (this.video && this.video.readyState >= 2) {
            const results = await this.detector.detect(this.video);
            if (results && results.length > 0) {
              const first = results[0];
              const raw = first.rawValue || first.raw || '';
              if (raw) {
                this.running = false;
                if (this.onSuccess) this.onSuccess(raw, first);
                return;
              }
            }
          }
        } catch (err) {
          if (this.onError) this.onError(err && err.message ? err.message : String(err));
        }
        await sleep(this.delayMs);
      }
    }

    async stop() {
      this.running = false;
      if (this.timer) {
        clearTimeout(this.timer);
        this.timer = null;
      }
      if (this.stream) {
        this.stream.getTracks().forEach(function(track) {
          try { track.stop(); } catch (e) {}
        });
        this.stream = null;
      }
      if (this.video) {
        try { this.video.pause(); } catch (e) {}
        this.video.srcObject = null;
      }
      if (this.container) {
        this.container.innerHTML = '';
      }
      this.video = null;
      this.detector = null;
    }
  }

  window.Html5Qrcode = Html5Qrcode;
})(window);

